228	/* ── Componente principal ────────────────────────────────────────── */
229	const AdminCategorias = () => {
230	  const [categorias, setCategorias] = useState([]);
231	  const [loading, setLoading] = useState(true);
232	  const [erro, setErro] = useState(null);
233	  const [modal, setModal] = useState(null); // null | 'nova' | categoria_obj
234	  const [removendo, setRemovendo] = useState(null);
235	
236	  const carregar = useCallback(() => {
237	    setLoading(true);
238	    getCategoriasGlobais()
239	      .then((d) => setCategorias(d.categorias ?? []))
240	      .catch((e) => setErro(e.message))
241	      .finally(() => setLoading(false));
242	  }, []);
243	
244	  useEffect(() => { carregar(); }, [carregar]);
245	
246	  const handleRemover = async (cat) => {
247	    if (!window.confirm(`Remover "${cat.name}"? Produtos vinculados perderão a categoria.`)) return;
248	    setRemovendo(cat.id);
249	    try {
250	      await removerCategoriaGlobal(cat.id);
251	      setCategorias((prev) => prev.filter((c) => c.id !== cat.id));
252	    } catch (e) {
253	      alert(e.message);
254	    } finally {
255	      setRemovendo(null);
256	    }
257	  };
258	
259	  return (
260	    <div className="min-h-screen bg-gray-50 dark:bg-zinc-900">
261	      <header className="bg-white dark:bg-zinc-800 border-b border-gray-200 dark:border-zinc-700 px-6 py-4 flex items-center justify-between">
262	        <div>
263	          <h1 className="text-xl font-bold text-gray-900 dark:text-zinc-100">Categorias</h1>
264	          <p className="text-sm text-gray-500 dark:text-zinc-400">Categorias globais da plataforma</p>
265	        </div>
266	        <AdminNav active="/admin/categorias" />
267	      </header>
268	
269	      <main className="p-6 max-w-5xl mx-auto">
270	        <div className="flex items-center justify-between mb-6">
271	          <p className="text-sm text-gray-500 dark:text-zinc-400">{categorias.length} categoria(s)</p>
272	          <button
273	            onClick={() => setModal('nova')}
274	            className="px-4 py-2 bg-blue-600 text-white text-sm font-semibold rounded-xl hover:bg-blue-700 flex items-center gap-2"
275	          >
276	            <Icon name="Plus" size={16} /> Nova Categoria
277	          </button>
278	        </div>
279	
280	        {erro && <p className="text-red-600 dark:text-red-400 text-sm mb-4 bg-red-50 dark:bg-red-950/30 rounded-lg px-4 py-3">{erro}</p>}
281	
282	        {loading ? (
283	          <div className="flex justify-center py-16">
284	            <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
285	          </div>
286	        ) : categorias.length === 0 ? (
287	          <div className="bg-white dark:bg-zinc-800 rounded-2xl border border-gray-200 dark:border-zinc-700 p-14 text-center">
288	            <Icon name="Tag" size={44} className="text-gray-200 dark:text-zinc-600 mx-auto mb-3" />
289	            <p className="text-gray-400 dark:text-zinc-500 mb-4">Nenhuma categoria cadastrada</p>
290	            <button onClick={() => setModal('nova')}
291	              className="px-5 py-2.5 bg-blue-600 text-white text-sm font-semibold rounded-xl hover:bg-blue-700">
292	              Criar primeira categoria
293	            </button>
294	          </div>
295	        ) : (
296	          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
297	            <AnimatePresence>
298	              {categorias.map((cat) => (
299	                <motion.div
300	                  key={cat.id}
301	                  initial={{ opacity: 0, scale: 0.95 }}
302	                  animate={{ opacity: 1, scale: 1 }}
303	                  exit={{ opacity: 0, scale: 0.9 }}
304	                  className="bg-white dark:bg-zinc-800 rounded-2xl border border-gray-100 dark:border-zinc-700 p-5 flex items-center gap-4 group hover:shadow-md transition-shadow"
305	                >
306	                  <div
307	                    className="w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-md flex-shrink-0"
308	                    style={{ background: `linear-gradient(135deg, ${cat.color_primary}, ${cat.color_secondary})` }}
309	                  >
310	                    <Icon name={cat.icon_name ?? 'Tag'} size={24} />
311	                  </div>
312	                  <div className="flex-1 min-w-0">
313	                    <p className="font-bold text-gray-900 dark:text-zinc-100">{cat.name}</p>
314	                    <p className="text-xs text-gray-400 dark:text-zinc-500 mt-0.5">
315	                      {cat.icon_name} · {cat.total_produtos ?? 0} produto(s)
316	                    </p>
317	                  </div>
318	                  <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
319	                    <button
320	                      onClick={() => setModal(cat)}
321	                      className="p-2 text-gray-400 dark:text-zinc-500 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/30 rounded-lg transition-colors"
322	                      title="Editar"
323	                    >
324	                      <Icon name="Pencil" size={15} />
325	                    </button>
326	                    <button
327	                      onClick={() => handleRemover(cat)}
328	                      disabled={removendo === cat.id}
329	                      className="p-2 text-gray-400 dark:text-zinc-500 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/30 rounded-lg transition-colors disabled:opacity-40"
330	                      title="Remover"
331	                    >
332	                      <Icon name="Trash2" size={15} />
333	                    </button>
334	                  </div>
335	                </motion.div>
336	              ))}
337	            </AnimatePresence>
338	          </div>
339	        )}
340	      </main>
341	
342	      {modal && (
343	        <Modal
344	          categoria={modal === 'nova' ? null : modal}
345	          onClose={() => setModal(null)}
346	          onSave={() => { setModal(null); carregar(); }}
347	        />
348	      )}
349	    </div>
350	  );
351	};
352	
353	export default AdminCategorias;
