4	@Injectable()
5	export class CategoriasService {
6	  constructor(private supabase: SupabaseService) {}
7	
8	  async listarGlobais() {
9	    const { data, error } = await this.supabase.client
10	      .from('categories')
11	      .select('id, name, icon_name, color_primary, color_secondary, created_at')
12	      .is('restaurant_id', null)
13	      .order('name');
14	
15	    if (error) throw error;
16	
17	    const catIds = (data ?? []).map((c) => c.id);
18	    let prodCount: Record<number, number> = {};
19	
20	    if (catIds.length > 0) {
21	      const { data: prods } = await this.supabase.client
22	        .from('products')
23	        .select('category_id')
24	        .in('category_id', catIds);
25	
26	      for (const p of prods ?? []) {
27	        prodCount[p.category_id] = (prodCount[p.category_id] ?? 0) + 1;
28	      }
29	    }
30	
31	    return {
32	      categorias: (data ?? []).map((c) => ({ ...c, total_produtos: prodCount[c.id] ?? 0 })),
33	      total: data?.length ?? 0,
34	    };
35	  }
36	
37	  async listarTiposEstabelecimento() {
38	    const { data, error } = await this.supabase.client
39	      .from('establishment_types')
40	      .select('id, name, icon_name')
41	      .order('name');
42	
43	    if (error) throw error;
44	    return { tipos: data ?? [] };
45	  }
46	
47	  async criarTipoEstabelecimento(body: { name: string; icon_name?: string }) {
48	    const { data, error } = await this.supabase.client
49	      .from('establishment_types')
50	      .insert({ name: body.name, icon_name: body.icon_name ?? 'Store' })
51	      .select()
52	      .single();
53	
54	    if (error) throw error;
55	    return data;
56	  }
57	
58	  async atualizarTipoEstabelecimento(id: number, body: { name?: string; icon_name?: string }) {
59	    const campos: Record<string, any> = {};
60	    if (body.name !== undefined) campos.name = body.name;
61	    if (body.icon_name !== undefined) campos.icon_name = body.icon_name;
62	
63	    const { data, error } = await this.supabase.client
64	      .from('establishment_types')
65	      .update(campos)
66	      .eq('id', id)
67	      .select()
68	      .single();
