772	      <div className="bg-white dark:bg-zinc-800 rounded-2xl w-full max-w-sm p-6">
773	        <h3 className="text-lg font-bold text-gray-900 dark:text-zinc-100 mb-4">Plano — {instalacao.nome_cliente}</h3>
774	        <form onSubmit={handleSubmit} className="space-y-4">
775	          <select value={planoId} onChange={(e) => setPlanoId(e.target.value)} required
776	            className="w-full border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
777	            <option value="">Selecione um plano...</option>
778	            {planosLocais.map((p) => (
779	              <option key={p.id} value={p.id}>{p.nome} — {fmt(p.valor)}/{p.periodicidade}</option>
780	            ))}
781	          </select>
782	          {erro && <p className="text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/30 rounded-lg px-3 py-2">{erro}</p>}
783	          <div className="flex gap-3">
784	            <button type="button" onClick={onClose}
785	              className="flex-1 py-2.5 border border-gray-300 dark:border-zinc-700 rounded-xl text-sm text-gray-700 dark:text-zinc-300 hover:bg-gray-50 dark:hover:bg-zinc-700/40">
786	              Cancelar
787	            </button>
788	            <button type="submit" disabled={salvando}
789	              className="flex-1 py-2.5 bg-blue-600 text-white rounded-xl text-sm font-semibold hover:bg-blue-700 disabled:opacity-50">
790	              {salvando ? 'Salvando...' : 'Salvar'}
791	            </button>
792	          </div>
793	        </form>
794	      </div>
795	    </div>
796	  );
797	};
798	
799	const TabInstalacoesLocais = () => {
800	  const [instalacoes, setInstalacoes] = useState([]);
801	  const [planosLocais, setPlanosLocais] = useState([]);
802	  const [loading, setLoading] = useState(true);
803	  const [erro, setErro] = useState(null);
804	  const [modalNova, setModalNova] = useState(false);
805	  const [modalPlano, setModalPlano] = useState(null);
