862	          <Icon name="HardDrive" size={44} className="text-gray-200 dark:text-zinc-600 mx-auto mb-3" />
863	          <p className="text-gray-400 dark:text-zinc-500 mb-4">Nenhuma instalação local cadastrada</p>
864	          <button onClick={() => setModalNova(true)}
865	            className="px-5 py-2.5 bg-blue-600 text-white text-sm font-semibold rounded-xl hover:bg-blue-700">
866	            Criar primeira instalação
867	          </button>
868	        </div>
869	      ) : (
870	        <div className="bg-white dark:bg-zinc-800 rounded-2xl border border-gray-200 dark:border-zinc-700 overflow-x-auto">
871	          <table className="w-full text-sm">
872	            <thead>
