883	              {instalacoes.map((inst) => {
884	                const assinatura = inst.assinaturas?.[0];
885	                return (
886	                  <tr key={inst.id} className={`border-b border-gray-200 dark:border-zinc-700 last:border-0 hover:bg-gray-50 dark:hover:bg-zinc-700/40 ${!inst.ativo ? 'opacity-50' : ''}`}>
887	                    <td className="px-4 py-3">
888	                      <p className="font-medium text-gray-900 dark:text-zinc-100">{inst.nome_cliente}</p>
889	                      {inst.contato && <p className="text-xs text-gray-400 dark:text-zinc-500">{inst.contato}</p>}
890	                    </td>
891	                    <td className="px-4 py-3">
892	                      <button onClick={() => copiarSerial(inst.serial)}
893	                        className="font-mono text-xs text-gray-500 dark:text-zinc-400 hover:text-blue-600 dark:hover:text-blue-400 flex items-center gap-1.5">
894	                        {inst.serial} <Icon name="Copy" size={12} />
895	                      </button>
896	                    </td>
897	                    <td className="px-4 py-3 text-gray-700 dark:text-zinc-300">
898	                      {assinatura?.planos?.nome ?? <span className="text-gray-400 dark:text-zinc-500">Sem plano</span>}
899	                    </td>
900	                    <td className="px-4 py-3">{assinatura ? <Badge status={assinatura.status} /> : '—'}</td>
901	                    <td className="px-4 py-3 text-gray-500 dark:text-zinc-400 text-xs">{fmtData(inst.ultimo_check_em)}</td>
902	                    <td className="px-4 py-3 whitespace-nowrap">
903	                      <div className="flex items-center gap-1">
904	                        <button onClick={() => setModalPlano(inst)}
905	                          className="p-2 text-gray-400 dark:text-zinc-500 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/40 rounded-lg"
906	                          title="Trocar plano">
907	                          <Icon name="Wallet" size={15} />
908	                        </button>
909	                        <button onClick={() => handleGerarFatura(inst)} disabled={gerando === inst.id}
910	                          className="p-2 text-gray-400 dark:text-zinc-500 hover:text-green-600 dark:hover:text-green-400 hover:bg-green-50 dark:hover:bg-green-950/40 rounded-lg disabled:opacity-40"
911	                          title="Gerar fatura">
912	                          <Icon name="FileText" size={15} />
913	                        </button>
914	                        <button onClick={() => handleToggleAtivo(inst)}
915	                          className="p-2 text-gray-400 dark:text-zinc-500 hover:text-amber-600 dark:hover:text-amber-400 hover:bg-amber-50 dark:hover:bg-amber-950/40 rounded-lg"
916	                          title={inst.ativo ? 'Revogar serial' : 'Reativar'}>
917	                          <Icon name={inst.ativo ? 'EyeOff' : 'Eye'} size={15} />
918	                        </button>
919	                      </div>
920	                    </td>
921	                  </tr>
922	                );
923	              })}
924	            </tbody>
925	          </table>
926	        </div>
927	      )}
928	
929	      {modalNova && (
930	        <ModalNovaInstalacao planosLocais={planosLocais} onClose={() => setModalNova(false)} onCriada={carregar} />
931	      )}
932	      {modalPlano && (
933	        <ModalTrocarPlanoInstalacao
934	          instalacao={modalPlano}
935	          planosLocais={planosLocais}
936	          onClose={() => setModalPlano(null)}
937	          onSalvo={() => { setModalPlano(null); carregar(); }}
938	        />
