657	  async adicionarItens(comandaId: number, garcomId: number, itens: ItemComandaBody[]) {
658	    if (!itens?.length) throw new BadRequestException('Informe ao menos 1 item');
659	
660	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
661	    if (comanda.status !== 'aberta') throw new BadRequestException('Comanda não está aberta');
662	
663	    const itensDiretos = itens.filter((i) => i.product_id != null);
664	    const itensCombo = itens.filter((i) => i.combo_id != null);
665	
666	    const prodIds = itensDiretos.map((i) => i.product_id as number);
667	    const { data: produtos, error: errProd } = await this.supabase.client
668	      .from('products')
669	      .select('id, price, is_active')
670	      .in('id', prodIds.length ? prodIds : [0]);
671	    if (errProd) throw errProd;
672	
673	    const prodMap = Object.fromEntries((produtos ?? []).map((p) => [p.id, p]));
674	    for (const item of itensDiretos) {
675	      const prod = prodMap[item.product_id as number];
676	      if (!prod) throw new BadRequestException(`Produto ${item.product_id} não encontrado`);
677	      if (!prod.is_active) throw new BadRequestException(`Produto ${item.product_id} inativo`);
678	    }
679	
680	    // Combo explode nas linhas dos produtos reais (mesma observação copiada pra cada
681	    // linha, já que não faz sentido dividir a nota do garçom entre os itens do combo).
682	    const linhasCombo = (
683	      await Promise.all(
684	        itensCombo.map(async (i) => {
685	          const linhas = await this.combosService.expandir(i.combo_id as number, i.quantity, comanda.restaurant_id);
686	          return linhas.map((l) => ({ ...l, observacao: i.observacao }));
687	        }),
688	      )
689	    ).flat();
690	
691	    const linhasDiretas: (ItemExpandido & { observacao?: string })[] = itensDiretos.map((i) => ({
692	      product_id: i.product_id as number,
693	      quantity: i.quantity,
694	      unit_price: prodMap[i.product_id as number].price,
695	      observacao: i.observacao,
696	    }));
697	
698	    const linhasFinais = [...linhasDiretas, ...linhasCombo];
699	
700	    const { error } = await this.supabase.client.from('order_items').insert(
701	      linhasFinais.map((l) => ({
702	        order_id: comandaId,
703	        product_id: l.product_id,
704	        quantity: l.quantity,
705	        unit_price: l.unit_price,
706	        observacao: l.observacao?.trim() || null,
707	        combo_nome: l.combo_nome ?? null,
708	        combo_quantidade: l.combo_quantidade ?? null,
709	        status: 'pendente',
710	      })),
711	    );
712	    if (error) throw error;
713	
714	    await this.estoque.decrementarItens(linhasFinais);
715	
716	    await this.recalcularTotal(comandaId);
717	    return this.obterComanda(comandaId, garcomId);
718	  }
719	
720	  private async garantirItemPendenteDoGarcom(comandaId: number, garcomId: number, itemId: number) {
721	    await this.garantirComandaDoGarcom(comandaId, garcomId);
722	
723	    const { data: item } = await this.supabase.client
724	      .from('order_items')
725	      .select('id, status, product_id, quantity')
726	      .eq('id', itemId)
