1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { listarImpressoras, getKdsItensRestaurante, marcarItemProntoRestaurante, reimprimirItemRestaurante, iniciarPreparoItemRestaurante, voltarStatusItemRestaurante, cancelarItemRestaurante, moverItemRestaurante, getMinhaEmpresa, getSalaoComandaDetalhe, editarItemComandaSalao } from '../../services/restauranteService';
4	import { printTicketSetor } from '../../utils/printComanda';
5	import { formatDuracao } from '../../utils/formatDuracao';
6	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
7	import { useNowTick } from '../../hooks/useNowTick';
8	import Icon from '../../components/AppIcon';
9	
10	// Card por item (não por mesa/comanda) com cronômetro ao vivo — mostra há quanto tempo
11	// o item chegou (aguardando) e, quando em preparo, há quanto tempo está preparando,
12	// pra dar visibilidade do tempo total gasto até ficar pronto.
13	const ItemCard = ({ item, posicao, now, ehPrimeiro, ehUltimo, onReimprimir, onIniciarPreparo, onMarcarPronto, onVoltar, onCancelar, onMover, onAbrirComanda, onSalvarObservacao }) => {
14	  const enviadoEm = new Date(item.enviado_em).getTime();
15	  const preparandoEm = item.preparando_em ? new Date(item.preparando_em).getTime() : null;
16	  const tempoEspera = (preparandoEm ?? now) - enviadoEm;
17	  const tempoPreparo = preparandoEm ? now - preparandoEm : 0;
18	  const tempoTotal = now - enviadoEm;
19	  const podeAbrirComanda = item.tipo === 'salao' && !!item.numero_comanda;
20	  const podeEditarObs = item.tipo === 'salao';
21	  const [editandoObs, setEditandoObs] = useState(false);
22	  const [obsInput, setObsInput] = useState(item.observacao ?? '');
23	  useEffect(() => { if (!editandoObs) setObsInput(item.observacao ?? ''); }, [item.observacao, editandoObs]);
24	
25	  const salvarObs = () => {
26	    onSalvarObservacao(item, obsInput);
27	    setEditandoObs(false);
28	  };
29	
30	  return (
31	    <div
32	      onClick={podeAbrirComanda ? () => onAbrirComanda(item.order_id) : undefined}
33	      title={podeAbrirComanda ? 'Ver comanda completa' : undefined}
34	      className={`bg-[#1A1A1A] border rounded-2xl overflow-hidden ${podeAbrirComanda ? 'cursor-pointer hover:border-[#FF441F]/60' : ''} ${item.garcom_nao_entregou ? 'border-red-500 ring-1 ring-red-500/40' : posicao === 1 ? 'border-yellow-400/70 ring-1 ring-yellow-400/30' : item.status === 'enviado' ? 'border-blue-500/40' : 'border-[#2A2A2A]'}`}>
35	      {item.garcom && (
36	        <div className="bg-white px-4 py-2">
37	          <p className="text-center text-lg font-black text-[#18181B] uppercase tracking-wide">{item.garcom}</p>
38	        </div>
39	      )}
40	      <div className="p-4">
41	      <div className="flex items-start justify-between mb-1 gap-2">
42	        <div className="flex items-start gap-2">
43	          <span className={`w-6 h-6 flex-shrink-0 rounded-lg flex items-center justify-center text-xs font-black mt-0.5 ${posicao === 1 ? 'bg-yellow-400 text-black' : 'bg-[#2A2A2A] text-white'}`}>
44	            {posicao}
45	          </span>
46	          {item.status === 'enviado' && onMover && (
47	            <div className="flex flex-col gap-0.5" onClick={(e) => e.stopPropagation()}>
48	              <button onClick={() => onMover(item, 'cima')} disabled={ehPrimeiro} title="Adiantar — subir na fila"
49	                className="w-5 h-4 flex items-center justify-center rounded text-[#71717A] enabled:hover:text-white enabled:hover:bg-[#2A2A2A] disabled:opacity-20">
50	                <Icon name="ChevronUp" size={13} />
51	              </button>
52	              <button onClick={() => onMover(item, 'baixo')} disabled={ehUltimo} title="Atrasar — descer na fila"
53	                className="w-5 h-4 flex items-center justify-center rounded text-[#71717A] enabled:hover:text-white enabled:hover:bg-[#2A2A2A] disabled:opacity-20">
54	                <Icon name="ChevronDown" size={13} />
55	              </button>
56	            </div>
57	          )}
58	          <div className="leading-tight">
59	            <p className="text-xl font-black text-white">Quantidade: {item.quantity}</p>
60	            <p className="text-lg font-bold text-white">Produto: {item.product_name}</p>
61	          </div>
62	        </div>
63	        <button onClick={(e) => { e.stopPropagation(); onReimprimir(item); }}
64	          className="text-[10px] font-bold text-orange-400 border border-orange-500/40 rounded-lg px-2 py-1 hover:bg-orange-500/10 flex items-center gap-1 flex-shrink-0">
65	          <Icon name="Printer" size={11} /> Reimpressão
66	        </button>
67	      </div>
68	      {posicao === 1 && <p className="text-[10px] font-bold text-yellow-400 uppercase tracking-wide mb-1">Próximo da fila</p>}
69	      {item.garcom_nao_entregou && (
70	        <p className="text-sm font-bold text-white bg-red-600 rounded px-1.5 py-0.5 mb-1 animate-pulse">
71	          Esse pedido não foi entregue — garçom não entregou
72	        </p>
73	      )}
74	      {item.is_auto_atendimento && (
75	        <p className="text-sm font-bold text-white bg-pink-600 rounded px-1.5 py-0.5 mb-1">
76	          Auto Atendimento — Mesa {item.mesa_numero ?? '?'}
77	        </p>
78	      )}
79	      {item.garcom_indo_buscar && (
80	        <p className={`text-sm font-bold text-white rounded px-1.5 py-0.5 mb-1 ${item.entregue_garcom ? 'bg-emerald-600' : 'bg-blue-600'}`}>
81	          {item.entregue_garcom ? 'Já entregue pelo garçom' : 'Garçom vindo buscar'}
82	        </p>
83	      )}
84	      {editandoObs ? (
85	        <div className="flex items-center gap-1.5 mb-1" onClick={(e) => e.stopPropagation()}>
86	          <input value={obsInput} onChange={(e) => setObsInput(e.target.value)} autoFocus
87	            placeholder="Observação..." className="flex-1 text-xs bg-[#111111] border border-[#3A3A3A] rounded-lg px-2 py-1 text-white focus:outline-none focus:border-[#FF441F]" />
88	          <button onClick={salvarObs} className="text-xs font-bold text-emerald-400">Salvar</button>
89	          <button onClick={() => setEditandoObs(false)} className="text-xs text-[#71717A]">Cancelar</button>
90	        </div>
91	      ) : item.observacao ? (
92	        <p onClick={podeEditarObs ? (e) => { e.stopPropagation(); setEditandoObs(true); } : undefined}
93	          className={`text-sm font-bold text-white bg-blue-600 rounded px-1.5 py-0.5 mb-1 animate-pulse ${podeEditarObs ? 'cursor-pointer' : ''}`}>
94	          Obs: {item.observacao}
95	        </p>
96	      ) : podeEditarObs ? (
97	        <button onClick={(e) => { e.stopPropagation(); setEditandoObs(true); }}
98	          className="flex items-center gap-1 mb-1 text-xs text-[#71717A] hover:text-white">
99	          <Icon name="MessageSquare" size={11} /> Adicionar observação
100	        </button>
101	      ) : null}
102	      <div className="flex items-center gap-2 text-base font-bold text-yellow-400 mb-2">
103	        <Icon name="MapPin" size={14} />
104	        <span>{item.mesa && item.cliente ? `${item.mesa} • ${item.cliente}` : item.mesa ?? item.cliente ?? (item.tipo === 'delivery' ? `Pedido #${item.order_id}` : 'Avulsa')}</span>
105	        {item.numero_comanda && (
106	          <>
107	            <span className="text-[#71717A]">•</span>
108	            <span>Comanda #{item.numero_comanda}</span>
109	          </>
110	        )}
111	        <span className={`ml-auto px-1.5 py-0.5 rounded-full text-[10px] font-bold ${item.tipo === 'delivery' ? 'bg-sky-500/20 text-sky-400' : 'bg-purple-500/20 text-purple-300'}`}>
112	          {item.tipo === 'delivery' ? 'Delivery' : 'Salão'}
113	        </span>
114	      </div>
115	      <div className="flex items-center gap-3 text-[11px] font-mono mb-3">
116	        <span className="flex items-center gap-1 text-blue-400">
117	          <Icon name="Clock" size={11} /> espera {formatDuracao(tempoEspera)}
118	        </span>
119	        {item.status === 'preparando' && (
120	          <span className="flex items-center gap-1 text-orange-400">
121	            <Icon name="Flame" size={11} /> preparo {formatDuracao(tempoPreparo)}
122	          </span>
123	        )}
124	        <span className="ml-auto text-[#71717A]">total {formatDuracao(tempoTotal)}</span>
125	      </div>
126	      <div className="flex gap-2" onClick={(e) => e.stopPropagation()}>
127	        {item.status !== 'enviado' && (
128	          <button onClick={() => onVoltar(item)} title="Desfazer — clicou errado"
129	            className="flex-shrink-0 px-3 py-2 bg-[#2A2A2A] hover:bg-[#3A3A3A] text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
130	            <Icon name="Undo2" size={13} /> Voltar
131	          </button>
132	        )}
133	        {item.status === 'enviado' ? (
134	          <>
135	            <button onClick={() => onCancelar(item)} title="Cancelar item"
136	              className="flex-shrink-0 px-3 py-2 bg-red-900/40 hover:bg-red-900/60 text-red-400 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
137	              <Icon name="X" size={13} /> Cancelar
138	            </button>
139	            <button onClick={() => onIniciarPreparo(item)}
140	              className="flex-1 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
141	              <Icon name="ChefHat" size={13} /> Iniciar Preparo
142	            </button>
143	          </>
144	        ) : item.status === 'pronto' ? (
145	          <div className="flex-1 py-2 bg-emerald-900/40 text-emerald-400 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
146	            <Icon name="Check" size={13} /> {item.entregue_garcom ? 'Entregue pelo garçom' : 'Entregue'}
147	          </div>
148	        ) : (
149	          <button onClick={() => onMarcarPronto(item.id)}
150	            className="flex-1 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
151	            <Icon name="Check" size={13} /> Pronto
152	          </button>
153	        )}
154	      </div>
155	      </div>
156	    </div>
157	  );
158	};
159	
