183	          {!comanda && !erro && <p className="text-sm text-[#71717A]">Carregando...</p>}
184	          {comanda && (
185	            <>
186	              <p className="text-xs text-[#71717A] mb-3">
187	                {comanda.mesas ? `Mesa ${comanda.mesas.numero}${comanda.mesas.nome ? ' - ' + comanda.mesas.nome : ''}` : comanda.cliente_mesa_nome}
188	                {comanda.garcons?.nome && ` • Garçom: ${comanda.garcons.nome}`}
189	                {comanda.aberto_por_nome && ` • Aberto por: ${comanda.aberto_por_nome}`}
190	              </p>
191	              <div className="space-y-2 mb-3">
192	                {(comanda.itens ?? []).map((item) => (
193	                  <div key={item.id} className="flex items-center justify-between gap-2 bg-[#111111] rounded-lg px-3 py-2">
194	                    <div>
195	                      <p className="text-sm font-bold text-white">{item.quantity}x {item.products?.name}</p>
196	                      {item.observacao && <p className="text-xs text-blue-400">Obs: {item.observacao}</p>}
197	                    </div>
198	                    <span className="text-xs text-[#71717A]">{fmt(item.quantity * item.unit_price)}</span>
199	                  </div>
200	                ))}
201	              </div>
202	              <div className="border-t border-[#2A2A2A] pt-3 flex items-center justify-between">
203	                <span className="text-xs font-bold text-[#71717A] uppercase">Total</span>
