214	// Linha de produção do Salão — visão unificada de TODOS os setores (cozinha, bar,
215	// salgados...) num painel só, dono acessa direto logado (sem link/token separado, mesmo
216	// padrão de acesso da tela de Cozinha do delivery). Cada setor é uma impressora
217	// cadastrada; itens vêm de order_items roteados pra ela (ver GET /restaurante/kds),
218	// lista PLANA por item (não agrupa por mesa/comanda), com cronômetro de espera/preparo.
219	const RestauranteProducao = () => {
220	  const navigate = useNavigate();
221	  const [impressoras, setImpressoras] = useState(null);
222	  const [itensPorImpressora, setItensPorImpressora] = useState({});
223	  const [restauranteNome, setRestauranteNome] = useState('');
224	  const [loading, setLoading] = useState(true);
225	  const [erro, setErro] = useState(null);
226	  const [lastUpdate, setLastUpdate] = useState(null);
227	  const [comandaAbertaId, setComandaAbertaId] = useState(null);
228	  const now = useNowTick();
229	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
230	  const [verTodosEntregues, setVerTodosEntregues] = useState({}); // { [impressoraId]: bool }
231	  const [busca, setBusca] = useState('');
232	  const prevItemIds = useRef(new Set());
233	  const firstLoad = useRef(true);
234	  const tocarSom = useNotificacaoSonora('cozinha');
235	
236	  useEffect(() => {
237	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
238	    listarImpressoras().then(setImpressoras).catch((e) => setErro(e.message));
239	  }, []);
240	
241	  const carregar = useCallback(async (lista) => {
242	    try {
243	      const resultados = await Promise.all(
244	        lista.map((imp) => getKdsItensRestaurante(imp.id).then((r) => [imp, r.itens ?? []])),
245	      );
246	      const porImpressora = {};
247	      const idsAgora = new Set();
248	      for (const [imp, itens] of resultados) {
249	        porImpressora[imp.id] = itens;
250	        for (const i of itens) idsAgora.add(i.id);
251	      }
252	
253	      if (!firstLoad.current) {
254	        const novos = [...idsAgora].filter((id) => !prevItemIds.current.has(id));
255	        if (novos.length > 0) tocarSom();
256	      } else {
257	        firstLoad.current = false;
258	      }
259	      prevItemIds.current = idsAgora;
260	
261	      setItensPorImpressora(porImpressora);
262	      setLastUpdate(new Date());
263	      setErro(null);
264	    } catch (e) {
265	      setErro(e.message);
266	    } finally {
267	      setLoading(false);
268	    }
269	  }, [tocarSom]);
270	
271	  useEffect(() => {
272	    if (!impressoras) return;
273	    if (impressoras.length === 0) { setLoading(false); return; }
274	    carregar(impressoras);
275	    const interval = setInterval(() => carregar(impressoras), 15000);
276	    return () => clearInterval(interval);
277	  }, [impressoras, carregar]);
278	
279	  const marcarPronto = async (itemId) => {
280	    await marcarItemProntoRestaurante(itemId);
281	    carregar(impressoras);
282	  };
283	
284	  const iniciarPreparo = async (item) => {
285	    await iniciarPreparoItemRestaurante(item.id);
286	    carregar(impressoras);
287	  };
288	
289	  const voltarItem = async (item) => {
290	    await voltarStatusItemRestaurante(item.id);
291	    carregar(impressoras);
292	  };
293	
294	  const moverItem = async (item, direcao) => {
295	    try {
296	      await moverItemRestaurante(item.id, direcao);
297	      carregar(impressoras);
298	    } catch (e) {
299	      alert(e.message);
300	    }
301	  };
302	
303	  const cancelarItem = async (item) => {
304	    if (!confirm(`Cancelar "${item.product_name}"? Esta ação não pode ser desfeita.`)) return;
305	    try {
306	      await cancelarItemRestaurante(item.id);
307	      carregar(impressoras);
308	    } catch (e) {
309	      alert(e.message);
310	    }
311	  };
312	
313	  const reimprimir = async (item, setorNome) => {
314	    try {
315	      const res = await reimprimirItemRestaurante(item.id);
316	      if (res.via === 'navegador') {
317	        printTicketSetor([item], { mesaLabel: item.mesa, cliente_mesa_nome: item.cliente }, setorNome);
318	      }
319	    } catch (e) {
320	      setErro(e.message);
321	    }
322	  };
323	
324	  const salvarObservacao = async (item, observacao) => {
325	    try {
326	      await editarItemComandaSalao(item.order_id, item.id, { observacao });
327	      carregar(impressoras);
328	    } catch (e) {
329	      setErro(e.message);
330	    }
331	  };
332	
333	  if (loading) return (
334	    <div className="min-h-screen bg-[#111111] flex items-center justify-center">
335	      <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
336	    </div>
337	  );
338	
339	  const todosItens = Object.values(itensPorImpressora).flat();
340	  const totalDelivery = todosItens.filter((i) => i.tipo === 'delivery').length;
341	  const totalSalao = todosItens.filter((i) => i.tipo === 'salao').length;
342	  const buscaNormalizada = busca.trim().toLowerCase();
343	  const passaBusca = (i) => {
344	    if (!buscaNormalizada) return true;
345	    const alvo = [i.cliente, i.mesa, i.mesa_numero, i.numero_comanda, i.garcom]
346	      .filter((v) => v !== null && v !== undefined)
347	      .join(' ')
348	      .toLowerCase();
349	    return alvo.includes(buscaNormalizada);
350	  };
351	  const passaFiltro = (i) => (filtroCanal === 'todos' || i.tipo === filtroCanal) && passaBusca(i);
352	  const totalItens = todosItens.filter(passaFiltro).length;
353	
354	  return (
355	    <div className="min-h-screen bg-[#111111]">
356	      <header className="bg-[#1A1A1A] border-b border-[#2A2A2A] px-5 py-3">
357	        <div className="flex items-center gap-4">
358	          <button onClick={() => navigate('/restaurante')} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
359	            <Icon name="ArrowLeft" size={18} />
360	          </button>
361	          <div className="flex items-center gap-2">
362	            <div className="w-8 h-8 bg-[#FF441F] rounded-lg flex items-center justify-center flex-shrink-0">
363	              <Icon name="ChefHat" size={16} className="text-white" />
364	            </div>
365	            <div>
366	              <p className="text-white font-black text-base leading-none">Linha de Produção — Salão</p>
367	              <p className="text-[#71717A] text-xs">{restauranteNome}</p>
368	            </div>
369	          </div>
370	          <div className="ml-auto flex items-center gap-2">
371	            <div className="flex items-center gap-2 text-xs text-[#71717A]">
372	              <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
373	              {lastUpdate?.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) ?? '—'}
374	            </div>
375	            <button onClick={() => carregar(impressoras ?? [])} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
376	              <Icon name="RefreshCw" size={16} />
377	            </button>
378	          </div>
379	        </div>
380	
381	        {/* Busca por cliente, mesa, comanda ou garçom */}
382	        <div className="flex items-center gap-2 mt-3 px-3 py-2 rounded-xl border border-[#2A2A2A] bg-[#111111] focus-within:border-[#FF441F]">
383	          <Icon name="Search" size={16} className="text-[#71717A] flex-shrink-0" />
384	          <input
385	            type="text"
386	            value={busca}
387	            onChange={(e) => setBusca(e.target.value)}
388	            placeholder="Buscar por cliente, mesa, comanda ou garçom..."
389	            className="flex-1 bg-transparent text-white text-sm placeholder:text-[#3A3A3A] outline-none"
390	          />
391	          {busca && (
392	            <button onClick={() => setBusca('')} className="text-[#71717A] hover:text-white flex-shrink-0">
393	              <Icon name="X" size={15} />
394	            </button>
395	          )}
396	        </div>
397	
398	        {/* Filtro de canal — Todos/Delivery/Salão */}
399	        <div className="flex items-center gap-2 mt-3">
400	          {[
401	            { key: 'todos', label: 'Todos', count: totalDelivery + totalSalao },
402	            { key: 'delivery', label: 'Delivery', count: totalDelivery },
403	            { key: 'salao', label: 'Salão', count: totalSalao },
404	          ].map((f) => (
405	            <button
406	              key={f.key}
407	              onClick={() => setFiltroCanal(f.key)}
408	              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
409	                filtroCanal === f.key
410	                  ? 'bg-[#FF441F] text-white'
411	                  : 'bg-[#111111] text-[#71717A] border border-[#2A2A2A] hover:text-white'
412	              }`}
413	            >
414	              {f.label}
415	              <span className={`px-1.5 py-0.5 rounded-full text-[10px] ${filtroCanal === f.key ? 'bg-white/20' : 'bg-[#2A2A2A]'}`}>{f.count}</span>
416	            </button>
417	          ))}
418	        </div>
419	      </header>
420	
421	      {erro && (
422	        <div className="mx-5 mt-4 bg-red-900/50 border border-red-700 rounded-xl px-4 py-3 text-sm text-red-400">{erro}</div>
423	      )}
424	
425	      {impressoras && impressoras.length === 0 ? (
426	        <div className="text-center py-20 px-5">
427	          <Icon name="Printer" size={48} className="text-[#2A2A2A] mx-auto mb-4" />
428	          <p className="text-[#71717A] text-lg font-semibold">Nenhuma impressora cadastrada</p>
429	          <p className="text-[#3A3A3A] text-sm mt-1">Cada setor (Cozinha, Bar, Salgados...) precisa de uma impressora cadastrada com esse setor.</p>
430	          <button onClick={() => navigate('/restaurante/impressoras')}
431	            className="mt-4 px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19]">
432	            Ir pra Impressoras
433	          </button>
434	        </div>
435	      ) : (
436	        <main className="p-5 max-w-6xl mx-auto space-y-8">
437	          {(impressoras ?? []).map((imp) => {
438	            const itens = (itensPorImpressora[imp.id] ?? []).filter(passaFiltro);
439	            const aguardando = itens.filter((i) => i.status === 'enviado');
440	            const preparando = itens.filter((i) => i.status === 'preparando');
441	            const entregues = itens
442	              .filter((i) => i.status === 'pronto')
443	              .sort((a, b) => new Date(b.pronto_em).getTime() - new Date(a.pronto_em).getTime());
444	            return (
445	              <div key={imp.id}>
446	                <div className="flex items-center gap-2 mb-3">
447	                  <div className="w-2.5 h-2.5 rounded-full bg-orange-400" />
448	                  <h2 className="text-white font-bold text-sm uppercase tracking-wider">{imp.setor}</h2>
449	                  {itens.length > 0 && (
450	                    <span className="bg-orange-500 text-white text-xs font-black px-2 py-0.5 rounded-full">
451	                      {itens.length}
452	                    </span>
453	                  )}
454	                </div>
455	                {itens.length === 0 ? (
456	                  <div className="rounded-2xl border-2 border-dashed border-[#2A2A2A] p-6 text-center mb-2">
457	                    <p className="text-[#71717A] text-sm">Nenhum item pendente em {imp.setor}</p>
458	                  </div>
459	                ) : (
460	                  <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
461	                    <div>
462	                      <p className="text-xs font-bold text-blue-400 uppercase tracking-wider mb-2">Aguardando Preparo</p>
463	                      {aguardando.length === 0 ? (
464	                        <p className="text-xs text-[#71717A]">Nenhum</p>
465	                      ) : (
466	                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-3">
467	                          {aguardando.map((item, idx) => (
468	                            <ItemCard key={item.id} item={item} posicao={idx + 1} now={now}
469	                              ehPrimeiro={idx === 0} ehUltimo={idx === aguardando.length - 1} onMover={moverItem}
470	                              onReimprimir={(it) => reimprimir(it, imp.setor)} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltarItem} onCancelar={cancelarItem} onAbrirComanda={setComandaAbertaId} onSalvarObservacao={salvarObservacao} />
471	                          ))}
472	                        </div>
473	                      )}
474	                    </div>
475	                    <div>
476	                      <p className="text-xs font-bold text-orange-400 uppercase tracking-wider mb-2">Em Preparo</p>
477	                      {preparando.length === 0 ? (
478	                        <p className="text-xs text-[#71717A]">Nenhum</p>
479	                      ) : (
480	                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-3">
481	                          {preparando.map((item, idx) => (
482	                            <ItemCard key={item.id} item={item} posicao={idx + 1} now={now}
483	                              onReimprimir={(it) => reimprimir(it, imp.setor)} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltarItem} onAbrirComanda={setComandaAbertaId} onSalvarObservacao={salvarObservacao} />
484	                          ))}
485	                        </div>
486	                      )}
487	                    </div>
488	                    <div>
489	                      <p className="text-xs font-bold text-emerald-400 uppercase tracking-wider mb-2">Entregues hoje</p>
490	                      {entregues.length === 0 ? (
491	                        <p className="text-xs text-[#71717A]">Nenhum</p>
492	                      ) : (
493	                        <>
494	                          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-3">
495	                            {(verTodosEntregues[imp.id] ? entregues : entregues.slice(0, 2)).map((item, idx) => (
496	                              <ItemCard key={item.id} item={item} posicao={idx + 1} now={now}
497	                                onReimprimir={(it) => reimprimir(it, imp.setor)} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltarItem} onAbrirComanda={setComandaAbertaId} onSalvarObservacao={salvarObservacao} />
498	                            ))}
499	                          </div>
500	                          {entregues.length > 2 && (
501	                            <button onClick={() => setVerTodosEntregues((v) => ({ ...v, [imp.id]: !v[imp.id] }))}
502	                              className="mt-3 w-full py-2 text-xs font-bold text-emerald-400 border border-emerald-500/30 rounded-xl hover:bg-emerald-500/10">
503	                              {verTodosEntregues[imp.id] ? 'Recolher / fechar a lista' : `Ver todos (${entregues.length})`}
504	                            </button>
505	                          )}
506	                        </>
507	                      )}
508	                    </div>
509	                  </div>
510	                )}
511	              </div>
512	            );
513	          })}
514	          {totalItens === 0 && (
515	            <div className="text-center py-16">
516	              <Icon name="UtensilsCrossed" size={48} className="text-[#2A2A2A] mx-auto mb-4" />
517	              <p className="text-[#71717A] text-lg font-semibold">Tudo tranquilo</p>
