523	
524	      <p className="text-center text-xs text-[#3A3A3A] py-4">Atualiza automaticamente a cada 15 segundos</p>
525	
526	      {comandaAbertaId && <ComandaModal orderId={comandaAbertaId} onFechar={() => setComandaAbertaId(null)} />}
527	    </div>
528	  );
529	};
