200	    const { data: pagamentos } = await this.supabase.client.from('comanda_pagamentos').select('valor, taxa_cartao_valor').eq('order_id', comandaId);
201	
202	    const subtotal = (itens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
203	    const totalTaxaCartao = (pagamentos ?? []).reduce((acc: number, p: any) => acc + (p.taxa_cartao_valor ?? 0), 0);
204	    const totalFinal = subtotal - (comanda?.desconto_valor ?? 0) + (comanda?.acrescimo_valor ?? 0) + (comanda?.gorjeta_valor ?? 0) + totalTaxaCartao;
205	    // total_pago tem que incluir a taxa de cada pagamento — ela já foi cobrada do
206	    // cliente junto com o valor base. Somar só p.valor (sem a taxa) fazia o saldo
207	    // devedor contar a taxa já paga como se ainda estivesse em aberto, cobrando ela
208	    // de novo no fechamento.
209	    const totalPago = (pagamentos ?? []).reduce((acc: number, p: any) => acc + p.valor + (p.taxa_cartao_valor ?? 0), 0);
210	
211	    return {
212	      subtotal: parseFloat(subtotal.toFixed(2)),
213	      total: parseFloat(totalFinal.toFixed(2)),
214	      total_pago: parseFloat(totalPago.toFixed(2)),
215	      saldo: parseFloat((totalFinal - totalPago).toFixed(2)),
216	    };
217	  }
218	
219	  // Lança uma saída automática no caixa aberto do restaurante — usado pra registrar troco
220	  // dado e gorjeta paga em dinheiro, sem o caixa precisar lançar isso manualmente depois.
221	  async registrarSaidaCaixa(restaurantId: number, descricao: string, valor: number, tipo: 'troco' | 'gorjeta' | 'estorno_pagamento') {
222	    if (!(valor > 0)) return;
223	    const { data: caixa } = await this.supabase.client
224	      .from('caixas')
225	      .select('id, saidas')
226	      .eq('restaurant_id', restaurantId)
227	      .eq('status', 'aberto')
228	      .maybeSingle();
229	    if (!caixa) return; // sem caixa aberto: melhor não travar o pagamento por isso
230	
231	    const saidas = (caixa.saidas ?? []) as any[];
232	    const nova = { descricao, valor, meio: 'dinheiro', tipo, criado_em: new Date().toISOString() };
233	    await this.supabase.client.from('caixas').update({ saidas: [...saidas, nova] }).eq('id', caixa.id);
234	  }
235	
236	  // Lança uma entrada automática no caixa aberto — usado pra registrar o dinheiro que o
237	  // cliente entregou de fato numa venda em espécie (não o valor da venda, o valor recebido).
238	  async registrarEntradaCaixa(restaurantId: number, descricao: string, valor: number, tipo: string) {
239	    if (!(valor > 0)) return;
240	    const { data: caixa } = await this.supabase.client
241	      .from('caixas')
242	      .select('id, entradas')
243	      .eq('restaurant_id', restaurantId)
244	      .eq('status', 'aberto')
245	      .maybeSingle();
246	    if (!caixa) return;
247	
248	    const entradas = (caixa.entradas ?? []) as any[];
249	    const nova = { descricao, valor, meio: 'dinheiro', tipo, criado_em: new Date().toISOString() };
250	    await this.supabase.client.from('caixas').update({ entradas: [...entradas, nova] }).eq('id', caixa.id);
251	  }
252	
253	  // Deletar (ou trocar a forma de) um pagamento em dinheiro já lançado não desfazia
254	  // sozinho o que aconteceu no caixa físico: nem a entrada (valor_recebido — ver
255	  // registrarEntradaCaixa) nem a saída de troco que ela gerou (ver registrarSaidaCaixa).
256	  // Corrigir um valor errado sem estornar os dois deixava dinheiro fantasma — e faltando
257	  // o troco de volta, o saldo ficava errado pro lado contrário (faltando dinheiro).
258	  async estornarPagamentoEmDinheiro(
259	    restaurantId: number,
260	    identificador: string,
261	    pagamento: { forma_pagamento: string; valor: number; valor_recebido?: number | null; troco?: number | null },
262	  ) {
263	    if (pagamento.forma_pagamento !== 'cash') return;
264	    const valorCreditado = pagamento.valor_recebido ?? pagamento.valor;
265	    await this.registrarSaidaCaixa(restaurantId, `Estorno pagamento removido - ${identificador}`, valorCreditado, 'estorno_pagamento');
266	    if ((pagamento.troco ?? 0) > 0) {
267	      await this.registrarEntradaCaixa(restaurantId, `Estorno troco (pagamento removido) - ${identificador}`, pagamento.troco as number, 'estorno_troco');
268	    }
269	  }
270	
271	  // Comanda cancelada/excluída não pode deixar pra trás nenhum pagamento em dinheiro já
272	  // lançado no caixa físico — senão o dinheiro de uma venda que não existe mais continua
273	  // contando (mesmo problema do estorno individual, só que a comanda inteira some).
274	  async estornarPagamentosDaComanda(restaurantId: number, comandaId: number, identificador: string) {
275	    const { data: pagamentos } = await this.supabase.client
276	      .from('comanda_pagamentos')
277	      .select('forma_pagamento, valor, valor_recebido, troco')
278	      .eq('order_id', comandaId);
279	    for (const pagamento of (pagamentos ?? []) as any[]) {
280	      await this.estornarPagamentoEmDinheiro(restaurantId, identificador, pagamento);
281	    }
282	  }
283	
284	  // Espécie disponível agora no caixa aberto — soma direto do ledger (fundo + entradas em
285	  // dinheiro − saídas em dinheiro), sem precisar reconsultar pedidos. Usado pra bloquear
286	  // troco ou sangria sem fundo suficiente.
287	  async saldoEspecieDisponivel(restaurantId: number): Promise<number> {
288	    const { data: caixa } = await this.supabase.client
289	      .from('caixas')
290	      .select('valor_inicial, entradas, saidas')
291	      .eq('restaurant_id', restaurantId)
292	      .eq('status', 'aberto')
293	      .maybeSingle();
294	    if (!caixa) return 0;
295	    const emDinheiro = (arr: any[]) => ((arr ?? []) as any[])
296	      .filter((x) => !x.meio || x.meio === 'dinheiro')
297	      .reduce((s: number, x: any) => s + (x.valor ?? 0), 0);
298	    const saldo = (caixa.valor_inicial ?? 0) + emDinheiro(caixa.entradas) - emDinheiro(caixa.saidas);
299	    return parseFloat(saldo.toFixed(2));
300	  }
301	
302	  // Registra um pagamento parcial — não fecha a comanda sozinho, só abate do saldo devedor.
303	  // Chamado tanto pelo garçom (informar forma de pagamento) quanto pelo caixa (conferência).
304	  // Em dinheiro, valorRecebido é o que o cliente entregou — troco é calculado e vira saída
305	  // automática no caixa (ver registrarSaidaCaixa).
306	  async registrarPagamento(
307	    comandaId: number,
308	    origem: 'garcom' | 'estabelecimento',
309	    valor: number,
310	    formaPagamento: string,
311	    restaurantId: number,
312	    valorRecebido?: number,
313	    identificador?: string,
314	    taxaCartaoValor?: number,
315	  ) {
316	    if (!valor || valor <= 0) throw new BadRequestException('Valor precisa ser maior que zero');
317	    if (!formaPagamento) throw new BadRequestException('Informe a forma de pagamento');
318	
319	    let troco: number | null = null;
320	    if (formaPagamento === 'cash' && valorRecebido !== undefined) {
321	      if (valorRecebido < valor) throw new BadRequestException('Valor recebido não pode ser menor que o valor a pagar');
322	      troco = parseFloat((valorRecebido - valor).toFixed(2));
323	      if (troco > 0) {
324	        const saldoEspecie = await this.saldoEspecieDisponivel(restaurantId);
325	        if (saldoEspecie < troco) {
326	          throw new BadRequestException(
327	            `Caixa não tem troco suficiente em espécie (disponível: R$ ${saldoEspecie.toFixed(2)}, necessário: R$ ${troco.toFixed(2)}). Registre uma Adição no caixa antes de finalizar esse pagamento.`,
328	          );
329	        }
330	      }
331	    }
332	
333	    const { error } = await this.supabase.client
334	      .from('comanda_pagamentos')
335	      .insert({
336	        order_id: comandaId, valor, forma_pagamento: formaPagamento, origem,
337	        valor_recebido: valorRecebido ?? null, troco, taxa_cartao_valor: taxaCartaoValor || null,
338	      });
339	    if (error) throw error;
340	
341	    if (formaPagamento === 'cash' && valorRecebido !== undefined) {
342	      await this.registrarEntradaCaixa(restaurantId, `Venda em dinheiro${identificador ? ` - ${identificador}` : ''}`, valorRecebido, 'venda_dinheiro');
343	      if (troco && troco > 0) {
344	        await this.registrarSaidaCaixa(restaurantId, `Troco${identificador ? ` - ${identificador}` : ''}`, troco, 'troco');
345	      }
346	    }
347	
348	    return this.saldoDevedor(comandaId);
349	  }
350	
351	  // Permissão default true (opt-out) — preserva o comportamento de quem já usava
352	  // isso sem restrição antes da permissão existir; dono desativa por garçom se quiser.
353	  async registrarPagamentoComoGarcom(comandaId: number, garcomId: number, valor: number, formaPagamento: string, podePagamentoParcial = true, valorRecebido?: number) {
354	    if (!podePagamentoParcial) throw new ForbiddenException('Você não tem permissão para registrar pagamento parcial');
355	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
356	    if (!['aberta', 'fechada_garcom'].includes(comanda.status)) {
357	      throw new BadRequestException('Comanda já foi paga ou cancelada');
358	    }
359	    const identificador = `Comanda #${comanda.numero_comanda ?? comandaId}`;

