205	  private async buscarPagamento(comandaId: number, pagamentoId: number) {
206	    const { data } = await this.supabase.client
207	      .from('comanda_pagamentos')
208	      .select('id, forma_pagamento, valor, valor_recebido, troco, troco_via_pix')
209	      .eq('id', pagamentoId)
210	      .eq('order_id', comandaId)
211	      .maybeSingle();
212	    if (!data) throw new NotFoundException('Pagamento não encontrado');
213	    return data;
214	  }
215	
216	  // Comanda já paga só pode ter a forma de pagamento corrigida (não valor) enquanto o
217	  // caixa dela ainda está aberto — o resumo do caixa é recalculado do zero a cada
218	  // fechamento (ver calcularResumo em restaurante.service.ts), então a correção reflete
219	  // automaticamente. Se o caixa já fechou, o resumo daquele fechamento já foi gravado e
220	  // congelado — corrigir aqui não atualizaria retroativamente, então bloqueia.
221	  private async garantirCaixaAbertoDaComanda(comanda: any) {
222	    if (!comanda.caixa_id) return;
223	    const { data: caixa } = await this.supabase.client
224	      .from('caixas').select('status').eq('id', comanda.caixa_id).maybeSingle();
225	    if (caixa && caixa.status !== 'aberto') {
226	      throw new BadRequestException('O caixa desta comanda já foi fechado — não é possível corrigir o pagamento automaticamente. Ajuste manualmente o fechamento desse caixa se necessário.');
227	    }
228	  }
229	
230	  // Caixa edita/remove qualquer pagamento da comanda (origem garçom ou estabelecimento).
231	  // O garçom também pode editar/remover, mas só o que ele mesmo lançou — ver
232	  // editarPagamentoComoGarcom/removerPagamentoComoGarcom em salao.service.ts.
233	  // Comanda paga: só a forma de pagamento pode mudar (ex: confirmou PIX por engano, era
234	  // dinheiro) — valor fica travado pra não reabrir saldo devedor de uma venda já fechada.

