private calcularResumo(
  pedidos: any[],
  saidas: any[],
  valor_inicial: number,
  entradas: any[] = [],
  pagamentosPorComanda?: Map<number, { valor: number; valor_recebido?: number | null; forma_pagamento: string; taxa_cartao_valor?: number }[]>,
) {
  const entregues = pedidos.filter((p) => this.STATUS_VENDA_FINALIZADA.includes(p.status));
  const total_saidas = saidas.reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
  const total_entradas = entradas.reduce((s: number, e: any) => s + (e.valor ?? 0), 0);

  // orders.total (comanda do salão) guarda só subtotal-desconto+acréscimo — a taxa de
  // cartão cobrada do cliente fica em comanda_pagamentos.taxa_cartao_valor. Entra num
  // bucket "taxa_cartao" à parte (não somado dentro de Cartão Crédito/Débito) pra
  // aparecer explícito na conferência de fechamento, sem esconder dentro da forma.
  let total_vendas = 0;
  const por_pagamento: Record<string, number> = {};
  // Taxa por forma (não some no bucket único "taxa_cartao") — pra tela de fechamento
  // poder mostrar "Débito R$161,70 + taxa R$11,32 = R$173,02" em vez de um total
  // de taxa solto, sem saber se veio do débito ou do crédito.
  const taxa_por_forma: Record<string, number> = {};
  // Dinheiro que o cliente entregou de fato (valor_recebido) — só pra exibição na
  // conferência de fechamento. O que entra/sai fisicamente do caixa já é lançado como
  // entrada/saída no ledger (ver registrarEntradaCaixa/registrarSaidaCaixa em
  // salao.service.ts), então especie_calculada usa entradas_especie/saidas_especie,
  // não esse valor — contar os dois juntos duplicaria a entrada em espécie.
  let cash_recebido = 0;
  for (const p of entregues) {
    const pagamentosComanda = p.canal === 'presencial' ? pagamentosPorComanda?.get(p.id) : undefined;
    if (pagamentosComanda?.length) {
      for (const pag of pagamentosComanda) {
        const m = pag.forma_pagamento ?? 'outro';
        const taxa = pag.taxa_cartao_valor ?? 0;
        por_pagamento[m] = (por_pagamento[m] ?? 0) + (pag.valor ?? 0);
        if (taxa > 0) {
          por_pagamento['taxa_cartao'] = (por_pagamento['taxa_cartao'] ?? 0) + taxa;
          taxa_por_forma[m] = (taxa_por_forma[m] ?? 0) + taxa;
        }
        total_vendas += (pag.valor ?? 0) + taxa;
        if (m === 'cash') cash_recebido += pag.valor_recebido ?? pag.valor ?? 0;
      }
    } else {
      const m = p.payment_method ?? 'outro';
      por_pagamento[m] = (por_pagamento[m] ?? 0) + (p.total ?? 0);
      total_vendas += p.total ?? 0;
      if (m === 'cash') cash_recebido += p.total ?? 0;
    }
  }

  const saidas_especie = saidas
    .filter((s: any) => !s.meio || s.meio === 'dinheiro')
    .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
  const entradas_especie = entradas
    .filter((e: any) => !e.meio || e.meio === 'dinheiro')
    .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
  const especie_calculada = valor_inicial + entradas_especie - saidas_especie;

  // saldo (contábil) já conta a venda em dinheiro via total_vendas — as entradas/saídas
  // automáticas de venda_dinheiro/troco (ver registrarEntradaCaixa/registrarSaidaCaixa em
  // salao.service.ts) representam a MESMA venda no ledger físico do caixa. Somar
  // total_entradas/total_saidas crus aqui contaria essa venda duas vezes. Filtra fora só
  // pra esse cálculo — total_entradas/total_saidas retornados continuam com tudo, pro
  // ledger (KPIs "Adições"/"Sangrias") mostrar os lançamentos automáticos normalmente.
  // estorno_troco compensa o troco original (já fora de saidas_saldo) quando um
  // pagamento com troco é corrigido/removido — mesma lógica do estorno_pagamento.
  const entradas_saldo = entradas
    .filter((e: any) => e.tipo !== 'venda_dinheiro' && e.tipo !== 'estorno_troco')
    .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
  // estorno_pagamento compensa uma venda_dinheiro que também já ficou de fora daqui
  // (pagamento corrigido/removido) — mesma lógica do troco, senão penaliza o saldo
  // líquido por uma venda que nem conta mais em total_vendas.
  const saidas_saldo = saidas
    .filter((s: any) => s.tipo !== 'troco' && s.tipo !== 'estorno_pagamento')
    .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);

  return {
    total_pedidos: pedidos.length,
    entregues: entregues.length,
    em_andamento: pedidos.filter((p: any) => this.STATUS_ABERTOS.includes(p.status) || this.COMANDA_STATUS_ABERTOS.includes(p.status)).length,
    cancelados: pedidos.filter((p: any) => p.status === 'canceled').length,
    total_vendas,
    total_saidas,
    total_entradas,
    saldo: valor_inicial + total_vendas + entradas_saldo - saidas_saldo,
    por_pagamento,
    taxa_por_forma,
    especie_calculada,
    saidas_especie,
    entradas_especie,
    cash_recebido,
  };
}

async getCaixa(restaurantId: number) {
  const { data: restaurantData } = await this.supabase.client
    .from('restaurants')
    .select('aparencia, saldo_caixa')
    .eq('id', restaurantId)
    .maybeSingle();
  const status_restaurante: boolean = (restaurantData?.aparencia?.aberto) === true;
  const saldo_caixa: number = restaurantData?.saldo_caixa ?? 0;

  // Saldo de caixas fechados que não passaram pelo fluxo de destinação
  // (criados antes da feature — o dinheiro físico ainda existe e deve ser contabilizado)
  const { data: caixasSemDestinacao } = await this.supabase.client
    .from('caixas')
    .select('resumo, destinacao_fechamento')
    .eq('restaurant_id', restaurantId)
    .eq('status', 'fechado')
    .is('destinacao_fechamento', null);

  const saldo_fechados_pendente: number = (caixasSemDestinacao ?? []).reduce((sum: number, c: any) => {
    return sum + (c.resumo?.saldo ?? 0);
  }, 0);

  const { data: caixa } = await this.supabase.client
    .from('caixas')
    .select('*')
    .eq('restaurant_id', restaurantId)
    .eq('status', 'aberto')
    .maybeSingle();

  if (!caixa) {
    const { data: expirado } = await this.supabase.client
      .from('caixas').select('*').eq('restaurant_id', restaurantId).eq('status', 'expirado').maybeSingle();
    return { status_restaurante, aberto: false, expirado: !!expirado, caixa_expirado: expirado ?? null, pedidos: [], resumo: null, saldo_caixa, saldo_fechados_pendente };
  }

  const { data: ordersData } = await this.supabase.client
    .from('orders')
    .select('id, total, frete_cobrado, troco_para, status, payment_method, canal, created_at, updated_at, customer_id, motoboy_id, caixa_id, mesa_id, cliente_mesa_nome, numero_comanda, customers(name, phone_e164), motoboys(name), mesas(numero, nome)')
    .eq('restaurant_id', restaurantId)
    .or(`caixa_id.eq.${caixa.id},and(caixa_id.is.null,created_at.gte.${caixa.aberto_em})`)
    .order('created_at', { ascending: false });

  const pedidos = ordersData ?? [];
  const saidas = (caixa.saidas ?? []) as any[];
  const entradas = (caixa.entradas ?? []) as any[];
  const pagamentosPorComanda = await this.buscarPagamentosPorComanda(pedidos);
  const resumo = this.calcularResumo(pedidos, saidas, caixa.valor_inicial, entradas, pagamentosPorComanda);

