  }

  const saidas_especie = saidas
    .filter((s: any) => !s.meio || s.meio === 'dinheiro')
    .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
  const entradas_especie = entradas
    .filter((e: any) => !e.meio || e.meio === 'dinheiro')
    .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
  const especie_calculada = valor_inicial + entradas_especie - saidas_especie;

  // saldo (contábil) já conta a venda em dinheiro via total_vendas — as entradas/saídas
  // automáticas de venda_dinheiro/troco (ver registrarEntradaCaixa/registrarSaidaCaixa em
  // salao.service.ts) representam a MESMA venda no ledger físico do caixa. Somar
  // total_entradas/total_saidas crus aqui contaria essa venda duas vezes. Filtra fora só
  // pra esse cálculo — total_entradas/total_saidas retornados continuam com tudo, pro
  // ledger (KPIs "Adições"/"Sangrias") mostrar os lançamentos automáticos normalmente.
  // estorno_troco compensa o troco original (já fora de saidas_saldo) quando um
  // pagamento com troco é corrigido/removido — mesma lógica do estorno_pagamento.
  const entradas_saldo = entradas
    .filter((e: any) => e.tipo !== 'venda_dinheiro' && e.tipo !== 'estorno_troco')
    .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
  // estorno_pagamento compensa uma venda_dinheiro que também já ficou de fora daqui
  // (pagamento corrigido/removido) — mesma lógica do troco, senão penaliza o saldo
  // líquido por uma venda que nem conta mais em total_vendas.
  const saidas_saldo = saidas
    .filter((s: any) => s.tipo !== 'troco' && s.tipo !== 'estorno_pagamento')
    .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);

  return {
    total_pedidos: pedidos.length,
    entregues: entregues.length,
    em_andamento: pedidos.filter((p: any) => this.STATUS_ABERTOS.includes(p.status) || this.COMANDA_STATUS_ABERTOS.includes(p.status)).length,
    cancelados: pedidos.filter((p: any) => p.status === 'canceled').length,
    total_vendas,
    total_saidas,
    total_entradas,
    saldo: valor_inicial + total_vendas + entradas_saldo - saidas_saldo,
    por_pagamento,
    taxa_por_forma,
    especie_calculada,
    saidas_especie,
    entradas_especie,
    cash_recebido,
  };
}

